import * as THREE from 'three';
import {createVoxelAnimal,VOXEL_IDS} from '../../src/museum/voxel-animals.js';
const data=SPECIES_DATA,host=document.querySelector('main'),scene=new THREE.Scene();scene.background=new THREE.Color('#ffffff');scene.add(new THREE.HemisphereLight('#fffbed','#8b9c81',2));const sun=new THREE.DirectionalLight('#ffe7bc',3);sun.position.set(-10,15,-20);scene.add(sun);
const camera=new THREE.OrthographicCamera(-13,13,10,-10,.1,100);camera.position.set(0,0,-30);camera.lookAt(0,0,0);
const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(1.5);renderer.setSize(1560,1200,false);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;host.append(renderer.domElement);
let models=[];for(let i=0;i<VOXEL_IDS.length;i++){const id=VOXEL_IDS[i],m=createVoxelAnimal(id),size=m.bounds.getSize(new THREE.Vector3()),scale=1.85/Math.max(size.x,size.y,size.z);m.group.scale.setScalar(scale);m.group.rotation.set(-.25,.65,0);const anchor=new THREE.Group();anchor.position.set((3.5-i%8)*3.25,8-Math.floor(i/8)*4,0);anchor.add(m.group);scene.add(anchor);models.push(m);const label=document.createElement('div');label.className='name';label.style.left=(i%8*12.5)+'%';label.style.top=(Math.floor(i/8)*20+17.5)+'%';label.textContent=data.find(x=>x.id===id)?.name||id;host.append(label);}
function draw(){renderer.render(scene,camera);}draw();document.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{for(const m of models){m.group.rotation.y=Number(b.dataset.angle);m.group.rotation.x=b.dataset.top?-1.05:-.25;}draw();}));document.body.dataset.ready='40';
